SELECT count( t1.`id` ) AS `totalNumber`, COUNT(CASE WHEN t1.`device_state` = '1' THEN 1 END) AS `normalNumber`, COUNT(CASE WHEN t1.`device_state` = '0' THEN 1 END) AS `offlineNumber`, 0 AS `troubleNumber`, 0 AS `alarmNumber` FROM ( SELECT DISTINCT `bd`.`id`, `bd`.`device_state` FROM `center_biz_device` `bd`
LEFT JOIN `center_biz_tag_ref` `tag_ref` ON `bd`.`id` = `tag_ref`.`business_key` LEFT JOIN `center_biz_tag` `tag` ON `tag`.`id` = `tag_ref`.`tag_id`
`tag`.`tag_code` in
#{tagCode}
) t1

select count(*)
from `center_biz_device`
where `id` != #{iotDeviceId,jdbcType=BIGINT}
and (`device_code` = #{deviceCode,jdbcType=VARCHAR}
     or (`device_name` = #{deviceName,jdbcType=VARCHAR}
         and `device_iot_prod_id` = #{productId,jdbcType=BIGINT}))
and `deleted` = 0
and `tenant` = #{tenant,jdbcType=INTEGER}

select `device_iot_prod_id`
from `center_biz_device`
where `id` = #{deviceId}

select `d`.`id`, `d`.`device_code`, `d`.`device_name`,`d`.`device_state` as `onlineState`, `d`.area_last_id as `area_id`, `p`.`prod_name` as `productName`, `p`.`prod_category_name` as `productCategoryName` from `center_biz_device` `d` left join `iot_prod_view` `p` on `d`.`device_iot_prod_id` = `p`.`id`
AND `p`.`prod_category_concat` like concat('%', #{query.productCategoryCode} ,'%')
AND `d`.`device_state` = #{query.deviceState}
AND `d`.`area_id` LIKE CONCAT('%',#{query.anyMatchedAreaId},'%')
and (`d`.`device_name` like concat('%',#{query.keyword,jdbcType=VARCHAR},'%') or `d`.`device_code` like concat('%',#{query.keyword,jdbcType=VARCHAR},'%'))
and `d`.`id` = #{query.deviceId,jdbcType=BIGINT}

select `d`.`id`, `d`.`device_code`, `d`.`device_name`,`d`.`device_state` as `onlineState`, `d`.area_last_id as `area_id`, `p`.`prod_name` as `productName`, `p`.`prod_category_name` as `productCategoryName` from `center_biz_device` `d` left join `iot_prod_view` `p` on `d`.`device_iot_prod_id` = `p`.`id`
AND `p`.`prod_category_concat` like concat('%', #{query.productCategoryCode} ,'%')
AND `d`.`device_state` = #{query.deviceState}
AND `d`.`area_id` LIKE CONCAT('%',#{query.anyMatchedAreaId},'%')
and (`d`.`device_name` like concat('%',#{query.keyword,jdbcType=VARCHAR},'%') or `d`.`device_code` like concat('%',#{query.keyword,jdbcType=VARCHAR},'%'))
and `d`.`id` = #{query.deviceId,jdbcType=BIGINT}

SELECT `prod_view`.`prod_category_code`, `prod_view`.`prod_category_concat`, `prod_view`.`prod_category_name`, COUNT( `dev`.`id` ) AS `totalNumber`, COUNT(CASE WHEN `dev`.`device_state` = '1' THEN 1 END) AS `normalNumber`, COUNT(CASE WHEN `dev`.`device_state` = '0' THEN 1 END) AS `offlineNumber` FROM `center_biz_device` `dev` INNER JOIN `center_biz_tag_ref` `tag_ref` ON `dev`.`id` = `tag_ref`.`business_key` INNER JOIN `iot_prod_view` `prod_view` ON `dev`.`device_iot_prod_id` = `prod_view`.`id`
`tag_ref`.`tag_id` = #{tagId}
GROUP BY `prod_view`.`prod_category_code`

select `thirdparty_id`
from `center_biz_device`
where `id` = #{deviceId}

SELECT count( t1.`id` ) AS `totalNumber`, COUNT(CASE WHEN t1.`device_state` = '1' THEN 1 END) AS `normalNumber`, COUNT(CASE WHEN t1.`device_state` = '0' THEN 1 END) AS `offlineNumber`, t1.`tag_code` FROM ( SELECT DISTINCT `bd`.`id`, `bd`.`device_state`, SUBSTRING_INDEX( `tag`.`tag_code`, ':', -1 ) AS `tag_code` FROM `center_biz_device` `bd` LEFT JOIN `center_biz_tag_ref` `tag_ref` ON `bd`.`id` = `tag_ref`.`business_key` LEFT JOIN `center_biz_tag` `tag` ON `tag`.`id` = `tag_ref`.`tag_id` WHERE 1=1
and `tag`.`tag_code` in
#{tagCode}
and `bd`.`create_time` <= #{period.end,jdbcType=TIMESTAMP}
) t1 GROUP BY t1.`tag_code`

SELECT COUNT( DISTINCT `bd`.`id` ) FROM `center_biz_device` `bd` LEFT JOIN `center_biz_tag_ref` `tag_ref` ON `bd`.`id` = `tag_ref`.`business_key` LEFT JOIN `center_biz_tag` `tag` ON `tag`.`id` = `tag_ref`.`tag_id` where 1=1
and `tag`.`tag_code` in
#{tagCode}
and `bd`.`create_time` <= #{period.end,jdbcType=TIMESTAMP}

SELECT count( DISTINCT `bd`.`id` ) as `deviceNum`, `iot_prod`.`prod_category_name` AS `categoryName` FROM `center_biz_device` `bd` LEFT JOIN `center_biz_tag_ref` `tag_ref` ON `bd`.`id` = `tag_ref`.`business_key` LEFT JOIN `center_biz_tag` `tag` ON `tag`.`id` = `tag_ref`.`tag_id` LEFT JOIN `iot_prod_view` `iot_prod` ON `bd`.`device_iot_prod_id` = `iot_prod`.`id` WHERE 1 = 1 AND `tag`.`tag_code` = #{tagCode}
and `bd`.`create_time` <= #{period.end,jdbcType=TIMESTAMP}
GROUP BY `iot_prod`.`prod_category_name`

SELECT COUNT( `dev`.`id` ) AS `expireNum` FROM `center_biz_device` `dev` INNER JOIN `center_biz_tag_ref` `tag_ref` ON `dev`.`id` = `tag_ref`.`business_key` INNER JOIN `center_biz_device_expand` `dev_expand` ON `dev`.`id` = `dev_expand`.`id`
`dev_expand`.`purchase_date` IS NOT NULL AND DATE_ADD(`dev_expand`.`purchase_date`, INTERVAL `dev_expand`.`useful_life` MONTH) <= now() and `tag_ref`.`tag_id` in
#{tagId}

SELECT `cbd`.`id`, `cbd`.`device_name`, `cbd`.`device_code`, `cbd`.`device_state`, `cbd`.`device_iot_prod_id`, `cbd`.`department_id`, `cbd`.`department_name`, `cbd`.`area_id`, `cbd`.`area_name`, `cbd`.`area_last_id`, `cbd`.`communication_time`, `cbd`.`manager_ids`, `cbd`.`thirdparty_id`, `cbd`.`thirdparty_cfg`, `cbd`.`create_by`, `cbd`.`create_time`, `ipv`.`prod_category_code` AS `productCategoryCode`, `ipv`.`prod_category_name` AS `productCategoryName`, `cbde`.`lnt_and_lat` AS `lntAndLat`, `cbde`.`location_des` FROM `center_biz_device` `cbd` LEFT JOIN `iot_prod_view` `ipv` ON `cbd`.`device_iot_prod_id` = `ipv`.`id` LEFT JOIN `center_biz_device_expand` `cbde` ON `cbde`.id = `cbd`.ID
`cbd`.`id` in
#{id}

SELECT COUNT(*)
FROM `center_biz_device`
WHERE `device_code` = #{deviceCode}
AND `id` != #{excludeDeviceId}
AND `deleted` = 0
